From 391334f40d17ca3c50f675ed567b4dda471a31a4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:21:58 +0100
Subject: [PATCH] wallpapers/image: add an option to hide system wallpapers

The image list mixes the wallpapers installed with the system with the
user's own ones, and there was no way to see only the latter. Add a
"Show System Wallpapers" toggle to the list's menu, keeping the one in use.

BUG: 515292
---
 .../imagepackage/contents/config/main.xml     |  4 ++
 .../contents/ui/ThumbnailsComponent.qml       | 47 ++++++++++++++++---
 .../image/imagepackage/contents/ui/config.qml |  2 +
 3 files changed, 46 insertions(+), 7 deletions(-)

diff --git a/wallpapers/image/imagepackage/contents/config/main.xml b/wallpapers/image/imagepackage/contents/config/main.xml
index 1c47869b78..d8f6800425 100644
--- a/wallpapers/image/imagepackage/contents/config/main.xml
+++ b/wallpapers/image/imagepackage/contents/config/main.xml
@@ -36,6 +36,10 @@
       <label>Sizing, cropping and positioning of the wallpaper image</label>
       <default>2</default>
     </entry>
+    <entry name="ShowSystemWallpapers" type="bool">
+      <label>Show the wallpapers installed with the system in the image list</label>
+      <default>true</default>
+    </entry>
     <entry name="SlideshowFoldersFirst" type="bool">
       <label>Display folders first when on slideshow</label>
       <default>false</default>
diff --git a/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml b/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml
index 730686fd57..f14fb498cf 100644
--- a/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml
+++ b/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml
@@ -24,28 +24,53 @@ Item {

     readonly property QtObject imageModel: (configDialog.currentWallpaper === "org.kde.image") ? sortedWallpaperModel : imageWallpaper.slideFilterModel

+    KItemModels.KSortFilterProxyModel {
+        id: userWallpaperModel
+        sourceModel: (configDialog.currentWallpaper === "org.kde.image" && !imageWallpaper.loading) ? imageWallpaper.wallpaperModel : null
+        // Hide the wallpapers installed with the system, but keep the one in use
+        filterRowCallback: (sourceRow, sourceParent) => {
+            const removableRole = sourceModel.KItemModels.KRoleNames.role("removable");
+            return sourceModel.data(sourceModel.index(sourceRow, 0, sourceParent), removableRole)
+                || sourceModel.indexOf(root.wallpaperConfiguration.Image) === sourceRow;
+        }
+    }
+
     KItemModels.KSortFilterProxyModel  {
         id: sortedWallpaperModel
         sortRole: Qt.DisplayRole
         sortCaseSensitivity: Qt.CaseInsensitive
         sortColumn: 0
-        sourceModel: (configDialog.currentWallpaper === "org.kde.image") ? imageWallpaper.wallpaperModel : null
+        // Switch models instead of filtering in place, which leaves stale delegates in the view
+        sourceModel: {
+            if (!userWallpaperModel.sourceModel) {
+                return null
+            }
+            return root.cfg_ShowSystemWallpapers ? userWallpaperModel.sourceModel : userWallpaperModel
+        }
+        function toWallpaperModelIndex(proxyIndex : var) : var {
+            const sourceIndex = mapToSource(proxyIndex)
+            return sourceModel === userWallpaperModel ? userWallpaperModel.mapToSource(sourceIndex) : sourceIndex
+        }
         function indexOf(image : string) : int {
-            if (!sourceModel) {
+            const wallpaperModel = userWallpaperModel.sourceModel
+            if (!wallpaperModel) {
                 return -1
             }
-            const idx = sourceModel.indexOf(image)
+            const idx = wallpaperModel.indexOf(image)

             if (idx < 0) {
                 return idx
             }

-            const sourceIndex = sourceModel.index(idx, 0)
+            let sourceIndex = wallpaperModel.index(idx, 0)
+            if (sourceModel === userWallpaperModel) {
+                sourceIndex = userWallpaperModel.mapFromSource(sourceIndex)
+            }
             return mapFromSource(sourceIndex).row
         }
         function openContainingFolder(listIndex : int) {
-            if (sourceModel) {
-                sourceModel.openContainingFolder(mapToSource(index(listIndex, 0)).row)
+            if (userWallpaperModel.sourceModel) {
+                userWallpaperModel.sourceModel.openContainingFolder(toWallpaperModelIndex(index(listIndex, 0)).row)
             }
         }
     }
@@ -57,7 +82,7 @@ Item {
             if (loading) {
                 return;
             }
-            if (configDialog.currentWallpaper === "org.kde.image" && imageModel.indexOf(cfg_Image) < 0) {
+            if (configDialog.currentWallpaper === "org.kde.image" && imageWallpaper.wallpaperModel.indexOf(cfg_Image) < 0) {
                 imageWallpaper.addUsersWallpaper(cfg_Image);
             }
             wallpapersGrid.resetCurrentIndex();
@@ -94,6 +119,14 @@ Item {
                     visible: configDialog.currentWallpaper == "org.kde.image"
                     onTriggered: root.openChooserDialog();
                 },
+                Kirigami.Action {
+                    checkable: true
+                    checked: root.cfg_ShowSystemWallpapers
+                    text: i18ndc("plasma_wallpaper_org.kde.image", "@action:inmenu", "Show System Wallpapers")
+                    displayHint: Kirigami.DisplayHint.AlwaysHide
+                    visible: configDialog.currentWallpaper == "org.kde.image"
+                    onToggled: root.cfg_ShowSystemWallpapers = checked
+                },
                 NewStuff.Action {
                     configFile: Kirigami.Settings.isMobile ? "wallpaper-mobile.knsrc" : "wallpaper.knsrc"
                     text: i18ndc("plasma_wallpaper_org.kde.image", "@action:button the new things being gotten are wallpapers", "Get New…")
diff --git a/wallpapers/image/imagepackage/contents/ui/config.qml b/wallpapers/image/imagepackage/contents/ui/config.qml
index 533cc1fff8..ff90f7793e 100644
--- a/wallpapers/image/imagepackage/contents/ui/config.qml
+++ b/wallpapers/image/imagepackage/contents/ui/config.qml
@@ -36,6 +36,8 @@ ColumnLayout {
     property int cfg_FillModeDefault
     property int cfg_SlideshowMode
     property int cfg_SlideshowModeDefault
+    property bool cfg_ShowSystemWallpapers: true
+    property bool cfg_ShowSystemWallpapersDefault: true
     property bool cfg_SlideshowFoldersFirst
     property bool cfg_SlideshowFoldersFirstDefault: false
     property alias cfg_Blur: blurRadioButton.checked
-- 
2.53.0
